def min_extra_chars(s, dictionary):
    def is_substring(word, s):
        return word in s

    def find_substrings(s, dictionary):
        substrings = []
        for i in range(len(s)):
            for j in range(i + 1, len(s) + 1):
                substrings.append(s[i:j])
        return substrings

    substrings = find_substrings(s, dictionary)
    used_chars = 0
    for substring in substrings:
        if is_substring(substring, s):
            used_chars += 1
    return len(s) - used_chars

def count_good_integers(num1, num2, min_sum, max_sum):
