def minCost(cost, time):
    n = len(cost)
    paid_painter_time = 0
    paid_painter_cost = 0
    free_painter_time = 0
    free_painter_cost = 0
    total_cost = 0

    for i in range(n):
        if i % 2 == 0:
            total_cost += cost[i]
            paid_painter_time += time[i]
            paid_painter_cost += cost[i]
        else:
            total_cost += cost[i]
            free_painter_time += time[i]
            free_painter_cost += cost[i]

    if paid_painter_time > free_painter_time:
        return paid_painter_cost + total_cost
    else:
        return free_painter_cost + total_cost

def minimumCost(nums, x):
    n = len(nums)
    dp = [[0] * (x + 1) for _ in range(n + 1)]

    for i in range(1, n + 1):
        dp[i][0] = 0
        for j in range(1, x + 1):
            dp[i][j] = dp[i - 1][j] + nums[i - 1]

    for i in range(1, n + 1):
        for j in range(1, x + 1):
            dp[i][j] = min(dp[i][j], dp[i - 1][j - 1] + nums[i - 1], dp[i - 1][j] + nums[i - 1])

    return dp[n][x]

def min_operations(s: str) -> str:
    # Initialize the result string and the stack of characters
    result = ""
    stack = []

    # Iterate over the characters in the input string
    for char in s:
        # If the stack is empty or the top of the stack is not the same as the current character, push the current character onto the stack
        if not stack or stack[-1] != char:
            stack.append(char)
        # Otherwise, pop the top of the stack and append it to the result string
        else:
            stack.pop()

    # If the stack is not empty, it means there are extra characters in the input string that need to be removed to make it a palindrome
    if stack:
        result = "".join(reversed(stack))

    return result

