def is_fascinating(n):
    # Check if the number contains all digits from 1 to 9 exactly once
    if set(str(n)) != set(str(1) + str(2) + str(3) + str(4) + str(5) + str(6) + str(7) + str(8) + str(9)):
        return False

    # Check if the number does not contain any 0's
    if '0' in str(n):
        return False

    # Check if the number is a multiple of 3
    if n % 3 != 0:
        return False

    # Check if the number is a multiple of 9
    if n % 9 != 0:
        return False

    return True

def minimize_string(s: str) -> int:
    def delete_closest_occurrences(s: str, i: int) -> int:
        left_occurrence = -1
        right_occurrence = -1
        for j in range(i, -1, -1):
            if s[j] == s[i]:
                left_occurrence = j
            if s[j] == s[i] and j > left_occurrence:
                left_occurrence = j

        for j in range(i + 1, len(s)):
            if s[j] == s[i]:
                right_occurrence = j
            if s[j] == s[i] and j < right_occurrence:
                right_occurrence = j

        if left_occurrence == -1:
            return len(s) - i
        elif right_occurrence == -1:
            return len(s) - i
        else:
            return min(left_occurrence, right_occurrence)

    return delete_closest_occurrences(s, 0)

def canTraverse(nums):
    def gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if gcd(nums[i], nums[j]) > 1:
                return True
    return False

def longestEqualSubarray(nums, k):
