def countSpecialPermutations(nums):
    MOD = 10**9 + 7
    n = len(nums)
    dp = [1] * n
    for i in range(1, n):
        for j in range(i):
            if nums[j] % nums[i] == 0:
                dp[i] = (dp[i] + dp[j]) % MOD
            elif nums[i] % nums[j] == 0:
                dp[i] = (dp[i] + dp[j]) % MOD
    return sum(dp) % MOD

