def prime_number_pairs(n):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    prime_numbers = [i for i in range(2, n + 1) if is_prime(i)]
    prime_pairs = []

    for i in range(len(prime_numbers)):
        for j in range(i + 1, len(prime_numbers)):
            if prime_numbers[i] + prime_numbers[j] == n:
                prime_pairs.append([prime_numbers[i], prime_numbers[j]])

    prime_pairs.sort(key=lambda x: x[0])

    return prime_pairs

def canBeZero(nums, k):
    n = len(nums)
    total_sum = sum(nums)
    if total_sum % k != 0:
        return False

    target_sum = total_sum // k
    dp = [0] * (target_sum + 1)
    dp[0] = 1

    for num in nums:
        for i in range(target_sum, num - 1, -1):
            dp[i] += dp[i - num]

    return dp[target_sum] == n

def count_expressions(n, x):
    MOD = 10**9 + 7
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        for j in range(1, i + 1):
            dp[i] += dp[i - j] * (1 << (i - j))
    return dp[n] % MOD

def longest_valid_substring(word, forbidden):
