        for j in range(i + 1, len(word) + 1):
            substring = word[i:j]
            if substring not in forbidden:
                max_length = max(max_length, len(substring))
    return max_length

def rearrange_string(s: str) -> str:
    vowels = 'aeiouAEIOU'
    consonants = 'bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ'
    vowel_index = [i for i, c in enumerate(s) if c in vowels]
    consonant_index = [i for i, c in enumerate(s) if c in consonants]
    vowel_index.sort(key=lambda x: ord(s[x]))
    consonant_index.sort(key=lambda x: ord(s[x]), reverse=True)
    result = []
    for i in range(len(s)):
        if i in vowel_index:
            result.append(s[i])
        elif i in consonant_index:
            result.append(s[i])
    return ''.join(result)

def maximumBeauty(nums, k):
    n = len(nums)
    dp = [0] * n
    for i in range(n):
        for j in range(i, n):
            dp[j] = max(dp[j], dp[j - 1] + 1)
            if nums[i] - k <= nums[j] <= nums[i] + k:
                dp[j] = max(dp[j], dp[j - 1] + 1)
    return max(dp)

def isGood(nums):
    n = len(nums)
    base = [1] * (n + 1)
    for i in range(1, n + 1):
        base[i] = i
    for num in nums:
        if num > n:
            return False
        if base[num] == n:
            base[num] = n - 1
        else:
