    dp = [0] * n
    dp[0] = 1
    for i in range(1, n):
        dp[i] = max(dp[i], dp[i-1] + 1)
        if i > 0 and usageLimits[i] > dp[i-1]:
            dp[i] = max(dp[i], dp[i-1] + 1)
    return dp[n-1]

def countSteppingNumbers(low, high):
