def can_make_equal(s1, s2):
    # Create a dictionary to store the frequency of each character in s1
    char_freq = {}
    for char in s1:
        if char in char_freq:
            char_freq[char] += 1
        else:
            char_freq[char] = 1

    # Create a dictionary to store the frequency of each character in s2
    char_freq_2 = {}
    for char in s2:
        if char in char_freq_2:
            char_freq_2[char] += 1
        else:
            char_freq_2[char] = 1

    # Check if the frequency of each character in s1 and s2 are equal
    for char, freq in char_freq.items():
        if char not in char_freq_2 or freq != char_freq_2[char]:
            return False

    # If the frequency of each character in s1 and s2 are equal, return True
    return True

