def countWays(s: str, t: str, k: int) -> int:
    n = len(s)
    mod = 10**9 + 7
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            if s[i - 1] == t[j - 1]:
                dp[i][j] = (dp[i - 1][j] + dp[i - 1][j - 1]) % mod
            else:
                dp[i][j] = dp[i - 1][j]

    return dp[n][k]

