def min_cost(s1, s2, x):
    n = len(s1)
    dp = [[0] * (n + 1) for _ in range(n + 1)]

    for i in range(n + 1):
        dp[i][0] = i * x
    for j in range(n + 1):
        dp[0][j] = j

    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = min(dp[i - 1][j] + 1, dp[i][j - 1] + 1, dp[i - 1][j - 1] + x)

    return dp[n][n]

def count_covered_points(nums):
    covered_points = 0
    for start, end in nums:
        covered_points += (end - start + 1)
    return covered_points

def min_operations(nums, k):
    nums.sort()
    total_operations = 0
    for i in range(k):
        total_operations += nums[i]
    return total_operations

def minRightShifts(nums):
    n = len(nums)
    nums.sort()
    return sum(nums[i] - nums[i - 1] for i in range(1, n))

def min_operations(num):
    num = list(num)
    count = 0
    while num:
        digit = num.pop(0)
        if digit % 25 == 0:
            count += 1
        else:
            num.insert(0, digit)
    return count

def max_odd_binary(s):
    max_num = ""
    for i in range(len(s)):
        if s[i] == '1':
            max_num += '1'
        else:
            max_num += '0'
    return max_num

def max_subarrays(nums):
    n = len(nums)
    dp = [[0] * n for _ in range(n)]
    for i in range(n):
        dp[i][i] = nums[i]
    for length in range(2, n + 1):
        for i in range(n - length + 1):
            j = i + length - 1
            dp[i][j] = min(nums[i] & nums[i + 1] & ... & nums[j], dp[i + 1][j - 1] + nums[i] & nums[j])
    return dp[0][n - 1]

def min_length(nums):
    n = len(nums)
    dp = [0] * n
    for i in range(1, n):
        for j in range(i):
            if nums[i] < nums[j]:
                dp[i] = min(dp[i], dp[j] + 1)
    return dp[n - 1]

def min_operations(nums):
    nums.sort()
    n = len(nums)
    res = 0
    for i in range(1, n - 1):
        if nums[i] != nums[i - 1] or nums[i] != nums[i + 1]:
            res += 1
    return res

def count_ways(nums):
    n = len(nums)
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        if nums[i - 1] > 0:
            dp[i] += dp[i - nums[i - 1]]
        if nums[i - 1] < 0:
            dp[i] += dp[i - nums[i - 1] - 1]
    return dp[n]

def longest_subsequence_sum(nums, target):
    dp = [0] * (target + 1)
    dp[0] = 0
    for num in nums:
        for i in range(target, num - 1, -1):
            dp[i] = max(dp[i], dp[i - num] + 1)
    return dp[target] if dp[target] != 0 else -1

def maximumSumOfSquares(nums, k):
    MOD = 10**9 + 7
    n = len(nums)
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 0
    for i in range(1, n + 1):
        for j in range(1, min(i, k + 1)):
            dp[i][j] = (dp[i - 1][j] + dp[i - 1][j - 1]) % MOD
    max_sum = 0
    for i in range(1, min(k + 1, n) + 1):
        max_sum = (max_sum + dp[n][i] * i) % MOD
    return max_sum

def max_triplet_value(nums):
    nums.sort()
    result = 0
    for i in range(len(nums) - 2):
        if i > 0 and nums[i] == nums[i - 1]:
            continue
        j, k = i + 1, len(nums) - 1
        while j < k:
            total = nums[i] - nums[j] * nums[k]
            if total < 0:
                result = max(result, total)
                j += 1
            else:
                k -= 1
    return result

def lastVisited(words):
    nums = []
    nums_reverse = []
    prev_count = 0
    for word in words:
        if word == "prev":
            prev_count += 1
        else:
            nums.append(int(word))
            nums_reverse.append(nums[-1])
            if prev_count > 0:
                nums_reverse.append(nums_reverse[-1 - prev_count])
    return nums_reverse

def min_sum(nums1, nums2):
    nums1.sort()
    nums2.sort()
    i, j = 0, 0
    sum1, sum2 = 0, 0
    while i < len(nums1) and j < len(nums2):
        if nums1[i] == 0:
            i += 1
        elif nums2[j] == 0:
            j += 1
        else:
            if nums1[i] < nums2[j]:
                sum1 += nums1[i]
                i += 1
            else:
                sum2 += nums2[j]
                j += 1
    if i < len(nums1):
        sum1 += nums1[i:]
    elif j < len(nums2):
        sum2 += nums2[j:]
    return sum1 if sum1 == sum2 else -1

def maxXOR(nums):
    max_xor = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            x = nums[i]
            y = nums[j]
            if abs(x - y) <= min(x, y):
                xor = x ^ y
                max_xor = max(max_xor, xor)
    return max_xor
def maxXOR(nums):
    max_xor = 0
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            x = nums[i]
            y = nums[j]
            xor = x ^ y
            max_xor = max(max_xor, xor)
    return max_xor

def min_steps(s):
    n = len(s)
    black_count = s.count('1')
    white_count = n - black_count
    steps = 0
    for i in range(n):
        if s[i] == '1':
            steps += 1
            if i + 1 < n and s[i + 1] == '0':
                s = s[:i] + '0' + s[i + 1:]
                n -= 1
        else:
            if i > 0 and s[i - 1] == '1':
                s = s[:i - 1] + '1' + s[i:]
                n += 1
    return steps

def maxScore(nums, k):
    max_count = 0
    count = {}
    for num in nums:
        count[num] = count.get(num, 0) + 1
        max_count = max(max_count, count[num])

    return max_count

def count_ways(n, limit):
    dp = [[0 for _ in range(limit + 1)] for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(1, limit + 1):
            if i <= j:
                dp[i][j] = dp[i - 1][j] + dp[i][j - 1]
            else:
                dp[i][j] = dp[i - 1][j]
    return dp[n][limit]

def is_palindrome(s, queries):
    n = len(s)
    answer = [True] * len(queries)

    for i, query in enumerate(queries):
        a, b, c, d = query
        if n // 2 <= c <= d:
            s = s[:a] + s[a:b][::-1] + s[b:d][::-1] + s[d:]
            if s == s[::-1]:
                answer[i] = False

    return answer

def count_occurrences(nums1, nums2):
    count1 = 0
    count2 = 0
    for num in nums1:
