def solve(h, w, t, grid):
    visited = set()
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]
    start = None
    goal = None
    for i in range(h):
        for j in range(w):
            if grid[i][j] == 'S':
                start = (i, j)
            elif grid[i][j] == 'G':
                goal = (i, j)
            elif grid[i][j] == 'o':
                visited.add((i, j))

    if start is None or goal is None:
        return -1

    queue = [(start, 0)]
    visited.add(start)
    while queue:
        (x, y), dist = queue.pop(0)
        if (x, y) == goal:
            return dist
        for dx, dy in directions:
            nx, ny = x + dx, y + dy
            if (0 <= nx < h) and (0 <= ny < w) and grid[nx][ny] != '#' and (nx, ny) not in visited:
                queue.append(((nx, ny), dist + 1))
                visited.add((nx, ny))

    return -1

