def process_string(s):
    stack = []
    for i, c in enumerate(s):
        if c == '(':
            stack.append(i)
        elif c == ')':
            if not stack:
                return ""
            start = stack.pop()
            if i - start == 1 and s[start] == '(':
                return s[:start] + s[i+1:]
            elif i - start == 2 and s[start] == '(' and s[i] == ')':
                return s[:start] + s[i+2:]
