def solve(N, M, A, B):
    # Create a graph to represent the superiorities
    graph = {}
    for i in range(N):
        graph[i] = set()

    for i in range(M):
        graph[A[i]].add(B[i])
        graph[B[i]].add(A[i])

    # Perform DFS to find the strongest programmer
    def dfs(node, visited):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                dfs(neighbor, visited)

    # Find the strongest programmer
    for i in range(N):
        if i not in visited:
            visited = set()
            dfs(i, visited)
            if len(visited) == N:
                return i

    return -1

