def solve(n, d):
    # Create a graph with n vertices
    graph = [[] for _ in range(n)]

    # Add edges to the graph
    for i in range(1, n):
        for j in range(i + 1, n):
            graph[i].append(j)
            graph[j].append(i)

    # Initialize the maximum weight
    max_weight = 0

    # Choose edges with the maximum weight
    for i in range(1, n):
        for j in range(i + 1, n):
            for k in range(i + 1, n):
                for l in range(j + 1, n):
                    # Check if the chosen edges are pairwise distinct
                    if i != j and i != k and j != k and i != l and j != l:
                        # Calculate the weight of the chosen edges
                        weight = d[i][j] + d[j][k] + d[k][l] + d[l][i]
                        # Update the maximum weight if necessary
                        if weight > max_weight:
                            max_weight = weight

    return max_weight

