def min_time(N, A, B, C, D):
    dp = [[float('inf')] * (N + 1) for _ in range(N + 1)]
    dp[1][1] = 0
    for i in range(2, N + 1):
        for j in range(1, N + 1):
            if i == j:
                dp[i][j] = 0
            else:
                dp[i][j] = min(dp[i - 1][j] + A * D[i - 1][j], dp[i][j - 1] + B * D[i - 1][j] + C)
    return dp[N][N]

