    graph = {}
    for i in range(1, n + 1):
        graph[i] = []

    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            graph[i].append(j)
            graph[j].append(i)

    visited = [False] * (n + 1)
    stack = [1]

    while stack:
        vertex = stack.pop()
        if not visited[vertex]:
            visited[vertex] = True
