def solve():
    T = input()
    N = int(input())
    bags = []
    for i in range(N):
        bags.append(list(map(int, input().split())))

    def make_equal(s, bag):
        if len(s) == len(T):
            return 0
        for i in range(len(s)):
            if s[i] != T[i]:
                s = s[:i] + T[i] + s[i+1:]
                bags[bag].remove(T[i])
                bags[bag].append(s[i])
                return make_equal(s, bag)
        return 1

    ans = 0
    for i in range(N):
        ans += make_equal(T, i)
    return ans

