def min_f(n, edges, c):
    graph = [[] for _ in range(n + 1)]
    for a, b in edges:
        graph[a].append(b)
        graph[b].append(a)

    visited = [False] * (n + 1)
    ans = 0
    for i in range(1, n + 1):
        if not visited[i]:
            ans += c[i]
            dfs(graph, i, visited, ans)

    return ans

def dfs(graph, v, visited, ans):
    visited[v] = True
    ans += c[v]
    for neighbor in graph[v]:
        if not visited[neighbor]:
            dfs(graph, neighbor, visited, ans)

