def is_good_string(s):
    count = {}
    for char in s:
        if char in count:
            count[char] += 1
        else:
            count[char] = 1
    for i in range(1, len(s) + 1):
        if count[i] > 0:
            if count[i] == 2:
                return "Yes"
            else:
                return "No"
    return "Yes"

