    n, m = map(int, input().split())
    k_list = []
    for _ in range(m):
        k, c = map(int, input().split())
        k_list.append(k)

    edges = []
    for i in range(m):
        s = list(map(int, input().split()))
        edges.append((s[0], s[1], c))

    def is_connected():
        visited = [False] * n
        queue = [0]
        visited[0] = True
        while queue:
            u = queue.pop(0)
            for v, w in edges[u]:
                if not visited[v]:
                    visited[v] = True
                    queue.append(v)

    def min_spanning_tree():
        parent = {}
        rank = {}
        for i in range(n):
            parent[i] = i
            rank[i] = 0
        for u, v, w in edges:
            if rank[u] > rank[v]:
                parent[v] = u
            elif rank[u] < rank[v]:
                parent[u] = v
            else:
                parent[u] = v
                rank[v] += 1
        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]
        def union(x, y):
            root_x = find(x)
            root_y = find(y)
            if root_x != root_y:
                if rank[root_x] > rank[root_y]:
                    parent[root_y] = root_x
                elif rank[root_x] < rank[root_y]:
                    parent[root_x] = root_y
                else:
                    parent[root_y] = root_x
                    rank[root_x] += 1
        for u, v, w in edges:
            union(u, v)
        tree_edges = []
        for i in range(n):
            tree_edges.append((i, find(i)))
        for i in range(n):
            for j in range(i + 1, n):
                if find(i) == find(j):
                    tree_edges.append((i, j))
        return sum(w for u, v in tree_edges)

    if is_connected():
        print(min_spanning_tree())
    else:
        print(-1)

