def solve(n, k, p):
    # Create a list of indices
    indices = list(range(1, n + 1))

    # Generate all good index sequences
    good_sequences = []
    for i in range(1 << n):
        sequence = []
        for j in range(n):
            if (i & (1 << j)) != 0:
                sequence.append(indices[j])
        if is_good_sequence(sequence):
            good_sequences.append(sequence)

    # Find the minimum value of i_K - i_1
    min_value = float('inf')
    for sequence in good_sequences:
        min_value = min(min_value, sequence[-1] - sequence[0])

    return min_value

def is_good_sequence(sequence):
    # Check if the sequence is a good index sequence
    for i in range(1, len(sequence)):
        if sequence[i] - sequence[i - 1] > 1:
            return False
    return True

