def max_distance_prime(nums):
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    prime_nums = [num for num in nums if is_prime(num)]
    if not prime_nums:
        return 0
    return max(prime_nums) - min(prime_nums)

def kth_smallest(coins, k):
    dp = [0] * (k + 1)
    dp[0] = 0
    for coin in coins:
        for i in range(coin, k + 1):
            dp[i] = min(dp[i], dp[i - coin] + 1)
    return dp[k]

