def min_cost(nums, cost1, cost2):
    total_cost = 0
    for num in nums:
        total_cost += num
    total_cost = total_cost // 2
    return (total_cost + cost1 + cost2) % (10**9 + 7)

def is_same_color(grid):
    def is_same_color_row(row):
        return all(cell == row[0] for cell in row)

    def is_same_color_col(col):
        return all(grid[i][col] == grid[0][col] for i in range(3))

    for i in range(3):
        if is_same_color_row(grid[i]) or is_same_color_col(i):
            return True

    return False
grid1 = [["B","W","B"],["B","W","W"],["B","W","B"]]
print(is_same_color(grid1))  # Output: True

grid2 = [["B","W","B"],["W","B","W"],["B","W","B"]]
print(is_same_color(grid2))  # Output: False

grid3 = [["B","W","B"],["W","B","W"],["B","W","W"]]
print(is_same_color(grid3))  # Output: True

def count_right_triangles(grid):
    n = len(grid)
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                if grid[i][j] == 1 and grid[j][k] == 1 and grid[k][i] == 1:
                    count += 1
    return count

def permutation_difference(s: str, t: str) -> int:
    s_dict = {}
    t_dict = {}
    for char in s:
        s_dict[char] = s_dict.get(char, 0) + 1
    for char in t:
        t_dict[char] = t_dict.get(char, 0) + 1

    return sum(abs(s_dict[char] - t_dict[char]) for char in s_dict)
print(permutation_difference("abc", "bac"))  # Output: 2
print(permutation_difference("abcde", "edbac"))  # Output: 12

def isSpecial(nums):
    for i in range(len(nums) - 1):
        if nums[i] % 2 == nums[i + 1] % 2:
            return False
    return True

def count_good_pairs(nums1, nums2, k):
    count = 0
    for i in range(len(nums1)):
        for j in range(len(nums2)):
            if nums1[i] % nums2[j] * k == 0:
                count += 1
    return count

def compress_string(word):
    comp = ""
    count = 1
    for i in range(1, len(word)):
        if word[i] == word[i - 1]:
            count += 1
        else:
            comp += str(count) + word[i - 1]
            count = 1
    comp += str(count) + word[-1]
    return comp

def min_substrings(s: str) -> int:
    n = len(s)
    count = [0] * 26
    for c in s:
        count[ord(c) - ord('a')] += 1

    ans = 0
    for i in range(26):
        if count[i] > 0:
            ans += count[i] * (count[i] - 1) // 2

    return ans
print(min_substrings("fabccddg"))  # Output: 3
print(min_substrings("abababaccddb"))  # Output: 2

def powerful_array(x):
    def generate_powerful_array(n):
        powers = [1]
        for i in range(1, n):
            powers.append(powers[-1] * 2)
        return powers

    powerful_array = generate_powerful_array(x)
    return powerful_array
