def xor_twice_numbers(nums):
    result = 0
    for num in nums:
        result ^= num
    return result

def find_index(nums, queries, x):
    result = []
    for query in queries:
        count = nums.count(x)
        if count < query:
            result.append(-1)
        else:
            result.append(nums.index(x, query - count))
    return result
